"""Capture explicit scenario assumptions without mutating inventory or policy."""
CSS='''.po-stock-assumptions{padding:14px;background:#f3f7ff;border:1px solid #bfd2ed;border-radius:8px;margin:14px 0}.po-stock-assumptions fieldset{border:0;padding:0;margin:0}.po-stock-assumptions textarea{width:100%;min-height:90px;font:inherit}.po-stock-scenario{padding:12px;background:#edf4ff;border:1px solid #bfd2ed;border-radius:7px;margin:12px 0}.po-stock-scenario p{font-size:13px;line-height:1.5}'''
JS=r'''
let purchaseStockPlanningDraft=()=>null;
(function stockAssumptions(){
 const form=$('form'),box=document.createElement('details');box.id='po-stock-assumptions';box.className='po-stock-assumptions';box.innerHTML='<summary>Simular cantidad con demanda y cobertura declaradas</summary><p>Supuestos internos para este artículo y fecha de pedido. No cambian el inventario, las reglas ni los parámetros de la empresa.</p><label><input type="checkbox" id="po-stock-enabled" style="width:auto;display:inline"> Declarar un escenario de planificación</label><fieldset id="po-stock-fields" disabled><div class="fields"></div></fieldset><p id="po-stock-assumptions-notice" role="status"></p>';
 $('po-conditions').append(box);const group=box.querySelector('.fields'),fields={};
 for(const [key,label,type] of [['available_at_order','Stock libre al inicio del pedido, reservas ya descontadas','number'],['daily_demand','Consumo previsto adicional a esas reservas (unidades/día)','number'],['lead_time_days','Plazo de recepción de esta compra (días)','number'],['target_days','Cobertura objetivo desde la recepción (días)','number'],['safety_stock','Stock de seguridad que deseas conservar','number'],['purchase_step','Unidad mínima o múltiplo de compra','number'],['actor','Responsable de los supuestos','text'],['source_reference','Referencia de esta planificación o de sus soportes','text']]){const l=document.createElement('label'),input=document.createElement('input');l.textContent=label;input.id='po-stock-'+key;input.type=type;input.required=true;if(type==='number'){input.min=key==='target_days'?'1':key==='purchase_step'?'0.000001':'0';input.max=['target_days','lead_time_days'].includes(key)?'365':'1000000000';input.step=key.endsWith('days')?'1':'any'}else input.maxLength=256;l.append(input);group.append(l);fields[key]=input}
 const l=document.createElement('label');l.textContent='Entradas pendientes: una por línea, DD/MM/AAAA; cantidad. Vacío si no hay. Solo entre pedido y fin de cobertura.';const receipts=document.createElement('textarea');receipts.id='po-stock-receipts';receipts.placeholder='Ejemplo de formato: 20/11/2026; 40';l.append(receipts);$('po-stock-fields').append(l);const ackLabel=document.createElement('label'),ack=document.createElement('input');ack.type='checkbox';ack.id='po-stock-ack';ack.required=true;ack.style.width='auto';ackLabel.append(ack,document.createTextNode(' Declaro estos supuestos y todas las entradas del período. El stock corresponde al inicio del pedido y el consumo no vuelve a contar las reservas descontadas. Son hipótesis sin aceptación ni verificación automática.'));$('po-stock-fields').append(ackLabel);
 const enabled=$('po-stock-enabled');let binding=null;
 function identity(){const a=state?.articles.find(a=>a.article_id===$('article').value);return {dataset_id:$('dataset').value,article_id:a?.article_id,unit:a?.unit_as_documented,documentary_fingerprint:state?.documentary_context.fingerprint,order_date:inputDateISO(form.elements.order_date.value)}}
 function clear(){enabled.checked=false;$('po-stock-fields').disabled=true;binding=null;for(const input of Object.values(fields))input.value='';receipts.value='';ack.checked=false;}
 enabled.onchange=()=>{if(enabled.checked){try{binding=identity();if(!binding.article_id||!binding.order_date)throw Error('Selecciona artículo y fecha del pedido antes de declarar la planificación.');$('po-stock-fields').disabled=false;$('po-stock-assumptions-notice').textContent='Supuestos vinculados a '+binding.article_id+' · '+stockDate(binding.order_date)+' · '+binding.unit+'.';}catch(e){clear();$('po-stock-assumptions-notice').textContent=e.message}}else{$('po-stock-fields').disabled=true;binding=null;}};
 purchaseStockPlanningDraft=()=>{if(!enabled.checked)return null;const now=identity();if(JSON.stringify(now)!==JSON.stringify(binding))throw Error('Han cambiado el artículo, fecha o expediente. Vuelve a declarar la planificación.');const raw={...binding,acknowledge:ack.checked,receipts:receipts.value.trim()?receipts.value.trim().split(/\n/).map(line=>{const parts=line.split(';');if(parts.length!==2)throw Error('Entradas pendientes: usa DD/MM/AAAA; cantidad por línea.');return {date:inputDateISO(parts[0].trim()),quantity:parts[1].trim().replace(',','.')}}):[]};for(const [key,input] of Object.entries(fields))raw[key]=input.value;return raw};
 function checkBinding(){if(!enabled.checked||!binding)return;try{if(JSON.stringify(identity())!==JSON.stringify(binding)){clear();$('po-stock-assumptions-notice').textContent='Planificación desactivada al cambiar artículo, fecha o expediente. Declara nuevos supuestos para este contexto.'}}catch{clear()}}
 form.addEventListener('change',checkBinding,true);$('dataset').addEventListener('change',checkBinding);new MutationObserver(checkBinding).observe($('summary'),{childList:true,subtree:true,characterData:true});form.addEventListener('reset',clear);
})();
function renderPurchaseStockScenario(parent,r){const box=document.createElement('section');box.className='po-stock-scenario';const h=document.createElement('h3');h.textContent='PLANIFICACIÓN DE STOCK · HIPÓTESIS DECLARADA';box.append(h);for(const text of ['Cantidad para el objetivo del escenario: '+stockNumber(r.scenario_quantity)+' '+r.assumptions.unit+' · Cantidad actual: '+stockNumber(r.current_quantity)+'.','Recepción supuesta: '+stockDate(r.arrival_date)+' · Fin de cobertura: '+stockDate(r.target_end)+'.',r.status==='PRE_DELIVERY_SHORTFALL'?'Hay una falta prevista antes de la recepción: cambiar solo la cantidad de esta compra no la resuelve.':'Cálculo al cierre del día según los supuestos declarados; no acredita necesidad ni viabilidad final.',r.basis,'Responsable: '+r.assumptions.actor+' · Referencia: '+r.assumptions.source_reference]){const p=document.createElement('p');p.textContent=text;box.append(p)}parent.append(box)}
'''
